import { NextApiResponse, NextApiRequest } from "next";
import axios from "axios";

export default async function USDCEURCconverter(
  req: NextApiRequest,
  res: NextApiResponse
) {
  try {
    const apiKey = "858c0971-0733-462d-92d2-51b5c53bc63d"; // Remplacez par votre clé API
    const url = 'https://api.0x.org/gasless/quote';
    const params = {
      chainId: 43114,
      sellToken: '0xB97EF9Ef8734C71904D8002F8b6Bc66Dd9c48a6E', // USDC
      buyToken: '0xC891EB4cbdEFf6e073e859e987815Ed1505c2ACD', // EURC
      sellAmount: '2000000', // 2 USDC en wei
      taker: '0x2DE81737589163266Ff70F89CCb12D0655C35853' // Adresse du preneur
    };

    const headers = {
      '0x-api-key': apiKey,
      '0x-version': 'v2'
    };

    const response = await axios.get(url, { params, headers });
    res.status(200).json(response.data);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Une erreur est survenue lors de la requête.' });
  }
}